        raise ValueError("N must be a positive integer")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        # Even level, go from top to bottom
        numerator = N
        denominator = level - N + 1
    else:
        # Odd level, go from bottom to top
